function nextGen(grid) {
  const h = grid.length, w = grid[0].length;
  // Write to a fresh grid — in-place would corrupt neighbor counts of unvisited cells.
  const out = Array.from({ length: h }, () => Array(w).fill(0));
  for (let r = 0; r < h; r++) {
    for (let c = 0; c < w; c++) {
      let n = 0;
      for (let dr = -1; dr <= 1; dr++) {
        for (let dc = -1; dc <= 1; dc++) {
          // Skip the cell itself when summing the 8 neighbors.
          if (dr === 0 && dc === 0) continue;
          const nr = r + dr, nc = c + dc;
          if (nr >= 0 && nr < h && nc >= 0 && nc < w) n += grid[nr][nc];
        }
      }
      // Live survives on 2 or 3; dead births on EXACTLY 3. Anything else dies.
      if (grid[r][c] === 1) out[r][c] = (n === 2 || n === 3) ? 1 : 0;
      else                  out[r][c] = (n === 3) ? 1 : 0;
    }
  }
  return out;
}
// Time O(h*w), Space O(h*w) for the new grid

